type Scope = 'Todos' | 'SPL' | '5to Elemento'
type View = 'dashboard' | 'events' | 'finance' | 'payroll' | 'settings'
type Unit = 'SPL' | '5to Elemento'
type Expense = { id: string; name: string; category: string; date: string; amount: number; paid: number; source?: 'payroll'; notes?:string|null; cashDate?: string; cashPayments?: {date:string;amount:number}[] }
type Payment = { id: string; date: string; amount: number; kind?:'payment'|'refund'; version?:number }
type EventRecord = { id: string; version:number; unit: Unit; name: string; client: string; venue: string; date: string; price: number | null; payrollBudget: number; expenseBudget: number; payrollActual: number; laborItems:DashboardCost[]; status: 'Confirmado' | 'Pendiente'; payments: Payment[]; expenses: Expense[] }
