  const loginWithDesktopGoogle=async()=>{const attempt=++loginAttempt.current;setBusy(true);setError('');try{const {flowId,authorizationUrl}=await desktopGoogleApi.start();await openDesktopAuthorization(authorizationUrl);const user=await waitForDesktopGoogle(flowId,desktopGoogleApi.status);if(loginAttempt.current===attempt)onLogin(user)}catch(error){if(loginAttempt.current===attempt)setError(error instanceof Error?error.message:'No pudimos completar el acceso con Google. Inténtalo nuevamente.')}finally{if(loginAttempt.current===attempt)setBusy(false)}}
